/*
	VIOC military_sites_statics (configured copy, optional). Server only.
	Called from Common\Init\Init_Location.sqf for towns with vioc_site_mult >= 2 (airports, airfields,
	military bases). Returns invisible helper objects that work like synced defense logics
	(cti_defense_kind ["VIOC_AA"] / ["VIOC_AT"]); the mission itself spawns, mans and replaces the
	statics (Server_ManageTownDefenses.sqf, Server_SpawnTownDefense.sqf, Server_OperateTownDefensesUnits.sqf).
	West/East reuse their own AA/AT town statics; the resistance gets CUP AAF statics, or vanilla ones without CUP.
	Helper = Land_ClutterCutter_small_F: invisible and not a helipad, so AI helicopters never use it as a landing pad.
*/
params ["_town"];
private _ret = [];

if (isNil "VIOC_SITES_STATICS_INIT") then {
	VIOC_SITES_STATICS_INIT = true;
	{
		private _sideStr = _x select 0;
		private _isGuer = _x select 1;
		{
			private _kind = _x select 0;
			private _list = +(missionNamespace getVariable [format ["CTI_%1_Defenses_%2", _sideStr, _x select 1], []]);
			if (count _list == 0 && _isGuer) then {
				_list = (_x select 2) select {isClass (configFile >> "CfgVehicles" >> _x)};
				if (count _list == 0) then {_list = (_x select 3) select {isClass (configFile >> "CfgVehicles" >> _x)}};
			};
			if (count _list > 0) then {missionNamespace setVariable [format ["CTI_%1_Defenses_%2", _sideStr, _kind], _list]};
		} forEach [
			["VIOC_AA", "AA", ["CUP_I_ZU23_AAF", "CUP_I_Igla_AA_pod_AAF"], ["I_static_AA_F"]],
			["VIOC_AT", "AT", ["CUP_I_SPG9_AAF", "CUP_I_Metis_AAF"], ["I_static_AT_F"]]
		];
	} forEach [["WEST", false], ["EAST", false], ["GUER", true]];
};

private _center = getPos _town;
private _kinds = ["VIOC_AA", "VIOC_AA", "VIOC_AT"];
private _dir0 = random 360;
{
	private _a = _dir0 + _forEachIndex * (360 / (count _kinds));
	private _p = [(_center select 0) + 60 * (sin _a), (_center select 1) + 60 * (cos _a), 0];
	_p = _p findEmptyPosition [0, 40, "I_static_AA_F"];
	if (count _p > 0 && {!(surfaceIsWater _p)} && {!(isOnRoad _p)}) then {
		private _h = "Land_ClutterCutter_small_F" createVehicleLocal _p;
		_h setPos _p;
		_h setDir _a;
		_h setVariable ["cti_defense_kind", [_x]];
		_ret pushBack _h;
	};
} forEach _kinds;

_ret
